// One item per page we intend to read. No web search exists on the gateway, so
// breadth of pages is where the evidence comes from instead.
const PATHS = String($env.RESEARCH_PATHS || '/,/about,/about-us,/services,/careers,/contact')
  .split(',').map((p) => p.trim()).filter(Boolean);

const out = [];

for (const item of $input.all()) {
  const body = item.json.body || item.json;
  let domain = String(body.domain || '').toLowerCase().trim();
  domain = domain.split('//').pop().split('/')[0];
  if (domain.startsWith('www.')) domain = domain.slice(4);

  const lead = {
    lead_id: body.lead_id || domain,
    company: body.company || domain,
    domain: domain,
    first_name: body.first_name || '',
    last_name: body.last_name || '',
    title: body.title || '',
    icp_description: body.icp_description || $env.ICP_DESCRIPTION || 'SME with a repetitive operations process, one clear decision maker, and budget for a paid tool.'
  };

  for (const path of PATHS) {
    out.push({ json: Object.assign({}, lead, {
      page_path: path,
      page_url: 'https://' + domain + (path === '/' ? '' : path)
    })});
  }
}

return out;

// Strip tags from each fetched page, drop the ones that 404'd or came back empty,
// and combine what is left into a single labelled blob per lead.
const PER_PAGE = 6000;
const TOTAL = 24000;

const strip = (raw) => {
  let text = '';
  let skipping = '';
  let pos = 0;
  while (pos < raw.length) {
    if (raw[pos] === '<') {
      const close = raw.indexOf('>', pos);
      const end = close === -1 ? raw.length : close;
      const name = raw.slice(pos + 1, end).toLowerCase().trim().split(' ')[0];
      if (!skipping && (name === 'script' || name === 'style' || name === 'noscript')) skipping = name;
      else if (skipping && name === '/' + skipping) skipping = '';
      pos = end + 1;
      if (!skipping) text += ' ';
      continue;
    }
    if (!skipping) text += raw[pos];
    pos++;
  }
  return text.split(/\s+/).join(' ').trim();
};

const planned = $('normalise request').all();
const byLead = {};

for (let i = 0; i < $input.all().length; i++) {
  const plan = (planned[i] || { json: {} }).json;
  const cleaned = strip(String(($input.all()[i].json || {}).data || ''));
  if (!plan.lead_id) continue;

  if (!byLead[plan.lead_id]) {
    byLead[plan.lead_id] = {
      lead_id: plan.lead_id, company: plan.company, domain: plan.domain,
      first_name: plan.first_name, last_name: plan.last_name, title: plan.title,
      icp_description: plan.icp_description, pages: [], sources: []
    };
  }

  // Under 200 characters is a 404 page or a JS shell, not content.
  if (cleaned.length < 200) continue;
  byLead[plan.lead_id].pages.push('--- ' + plan.page_url + ' ---\n' + cleaned.slice(0, PER_PAGE));
  byLead[plan.lead_id].sources.push({ title: plan.page_path, source_url: plan.page_url });
}

return Object.keys(byLead).map((id) => {
  const lead = byLead[id];
  const blob = lead.pages.join('\n\n').slice(0, TOTAL);
  return { json: {
    lead_id: lead.lead_id, company: lead.company, domain: lead.domain,
    first_name: lead.first_name, last_name: lead.last_name, title: lead.title,
    icp_description: lead.icp_description,
    pages_text: blob || '(no page on this domain returned readable content)',
    sources: lead.sources,
    pages_read: lead.sources.length,
    site_fetched: lead.sources.length > 0
  }};
});

// The gateway has no web search, so 'sources' are the pages we actually fetched.
// That is a smaller claim than a search-backed one, and it is an honest one.
const leads = $('strip and combine pages').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const lead = leads[i].json;
  const res = $input.all()[i].json || {};
  const prose = String(((((res.choices || [])[0]) || {}).message || {}).content || '').trim();

  out.push({ json: Object.assign({}, lead, {
    research_notes: prose,
    finish_reason: ((((res.choices || [])[0]) || {}).finish_reason) || ''
  })});
}

return out;

// output_config.format guarantees a single JSON text block. Still guard the parse:
// a hard failure here is better than a half-populated CRM row.
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const lead = $('collect research').all()[i].json;
  const res = $input.all()[i].json || {};
  const text = String(((((res.choices || [])[0]) || {}).message || {}).content || '').trim();

  if (!text) {
    throw new Error('No content for ' + lead.lead_id + ' (finish_reason: ' + ((((res.choices || [])[0]) || {}).finish_reason || 'none') + ')');
  }

  // Some gateway models fence JSON even when a schema is set.
  const raw = text.startsWith('```') ? text.split('```').filter(function (p) { return p.trim().indexOf('{') === 0; })[0] || text : text;

  let data;
  try {
    data = JSON.parse(raw);
  } catch (e) {
    throw new Error('Unparseable extraction for ' + lead.lead_id + ': ' + raw.slice(0, 200));
  }

  out.push({ json: {
    lead_id: lead.lead_id,
    company: lead.company,
    domain: lead.domain,
    first_name: lead.first_name,
    last_name: lead.last_name,
    title: lead.title || data.decision_maker_role,
    industry: data.industry,
    size_hint: data.size_hint,
    what_they_sell: data.what_they_sell,
    recent_trigger: data.recent_trigger,
    visible_pain: data.visible_pain,
    decision_maker_role: data.decision_maker_role,
    fit_score: data.fit_score,
    fit_reason: data.fit_reason,
    evidence: data.evidence,
    unknowns: data.unknowns,
    site_fetched: lead.site_fetched,
    stage: 'researched',
    researched_at: new Date().toISOString()
  }});
}

return out;
